package drone_lifecycle_governor.Drone_Lifecycle_Governor

import org.sireum._
import art.Art
import drone_lifecycle_governor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait FlightReadinessOwner_governorProcess_flightReadinessOwner_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner)
  }

  /** helper function to set the values of all input ports.
   * @param navigationCondition payload for data port navigationCondition
   * @param radioCondition payload for data port radioCondition
   */
  def put_concrete_inputs(navigationCondition : Drone_Lifecycle_Governor.NavigationCondition.Type,
                          radioCondition : Drone_Lifecycle_Governor.RadioCondition.Type): Unit = {
    put_navigationCondition(navigationCondition)
    put_radioCondition(radioCondition)
  }


  /** helper function to check FlightReadinessOwner_governorProcess_flightReadinessOwner's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param flightQualification method that will be called with the value of the outgoing data
   *        port 'flightQualification'.
   */
  def check_concrete_output(flightQualification: Drone_Lifecycle_Governor.FlightQualification.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val flightQualificationValue: Drone_Lifecycle_Governor.FlightQualification.Type = get_flightQualification().get
    if(!flightQualification(flightQualificationValue)) {
      testFailures = testFailures :+ st"'flightQualification' did not match expected: value of the outgoing data port is ${flightQualificationValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_navigationCondition(value : Drone_Lifecycle_Governor.NavigationCondition.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner.operational_api.navigationCondition_Id, Drone_Lifecycle_Governor.NavigationCondition_Payload(value))
  }

  // setter for in DataPort
  def put_radioCondition(value : Drone_Lifecycle_Governor.RadioCondition.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner.operational_api.radioCondition_Id, Drone_Lifecycle_Governor.RadioCondition_Payload(value))
  }

  // getter for out DataPort
  def get_flightQualification(): Option[Drone_Lifecycle_Governor.FlightQualification.Type] = {
    val value: Option[Drone_Lifecycle_Governor.FlightQualification.Type] = get_flightQualification_payload() match {
      case Some(Drone_Lifecycle_Governor.FlightQualification_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port flightQualification.  Expecting 'Drone_Lifecycle_Governor.FlightQualification_Payload' but received ${v}")
      case _ => None[Drone_Lifecycle_Governor.FlightQualification.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_flightQualification_payload(): Option[Drone_Lifecycle_Governor.FlightQualification_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_flightReadinessOwner.initialization_api.flightQualification_Id).asInstanceOf[Option[Drone_Lifecycle_Governor.FlightQualification_Payload]]
  }

}
